-- ════════════════════════════════════════════════════════
-- 214 — Lot 5 du second recensement : les requalifications
-- ────────────────────────────────────────────────────────
-- Des noms que le recensement testait comme des maisons et qui sont des
-- lignes, des collaborations ou des marques rachetees. Ils entrent dans
-- le `gamme` de la maison qui les possede — six langues — et chaque
-- notice dit ce qu'ils sont. Onze maisons touchees, seize lignes :
--   Black Label Trading   Black Works Studio
--   Aganorsa Leaf         Condega
--   J.C. Newman           Brick House, Perla del Mar, Quorum
--   La Aurora             Leon Jimenes
--   Drew Estate           Herrera Esteli, Kentucky Fire Cured
--   Rocky Patel           Hamlet
--   Tatuaje               Cabaiguan
--   RoMa Craft            Baka
--   A.J. Fernandez        Enclave, Dias de Gloria
--   Espinosa              601
--   Davidoff              Cusano
--   Warped                Guardian of the Farm, Cloud Hopper
--
-- UNE FICHE CORRIGEE : J.C. Newman disait « la famille ne roule rien
-- elle-meme ». Faux depuis 2011 : PENSA, a Esteli, roule Quorum, Perla
-- del Mar et Brick House, plus de cent mille cigares par jour, sous la
-- co-direction d'Omar Ortez (Agrotabacos). Le paragraphe est remplace en
-- six langues et la fiche dit qu'une premiere version se trompait.
--
-- Deja faits par des lots precedents : Cuba Aliados/Puros Indios/Roly
-- (Oliva, 207), Flores y Rodriguez (PDR, 209), Nomad -> Ezra Zion (la
-- fiche Nomad le disait deja), CroMagnon/Intemperance (RoMa).
-- Non traites, et pourquoi : Archetype/Psyko Seven — Ventura n'a pas de
-- fiche ; Lost & Found — une societe a part, pas une ligne de Caldwell ;
-- Belinda — marque retiree, aucune source verifiee ; Deadwood/Isla del
-- Sol/20 Acre Farm/Indomina — non sources dans ce lot.
--
-- `gamme` lu dans la base et reecrit en litteral complet, comme
-- `producer_countries.brands` dans les lots precedents.
-- ════════════════════════════════════════════════════════

-- ── Black Label Trading Co. ──
UPDATE `brands` SET `gamme` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","wrapper":"Assemblage Oveja Negra","vitolas":["Robusto","Toro","Petit Lancero"],"story":"« Les derniers sacrements » — la gamme fondatrice, et celle qui a donné son ton à toute l''iconographie de la maison. Corsée, roulée à l''Oveja Negra."},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","wrapper":"Assemblage Oveja Negra","vitolas":["Robusto","Toro"],"story":"Le pendant du Last Rites, dans le même registre liturgique. Feuilles du Nicaragua, du Honduras, de San Andrés et d''Équateur."},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","wrapper":"Assemblage Oveja Negra","vitolas":["Robusto","Toro"],"story":"La sainte Mort du culte populaire mexicain, dessinée par James Brown lui-même. La maison va au bout de son imagerie plutôt que de la suggérer."},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","wrapper":"Habano d''Équateur","vitolas":[],"story":"Le second nom de James Brown, novembre 2015, même fabrique — Oveja Negra — pour les assemblages moins orthodoxes. NBK, Killer Bee et Rorschach ont ouvert. Le recensement de cet atlas le prenait pour une maison à part."}]' WHERE `name` = 'Black Label Trading Co.';
UPDATE `brands` SET `gamme_en` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","wrapper":"Oveja Negra blend","vitolas":["Robusto","Toro","Petit Lancero"],"story":"\\"The last rites\\" — the founding range, and the one that set the tone for the whole of the house''s iconography. Full-bodied, rolled at Oveja Negra."},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","wrapper":"Oveja Negra blend","vitolas":["Robusto","Toro"],"story":"The counterpart to Last Rites, in the same liturgical register. Leaves from Nicaragua, Honduras, San Andrés and Ecuador."},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","wrapper":"Oveja Negra blend","vitolas":["Robusto","Toro"],"story":"The Holy Death of Mexican popular devotion, drawn by James Brown himself. The house carries its imagery through rather than merely hinting at it."},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"James Brown''s second name, November 2015, same factory — Oveja Negra — for the less orthodox blends. NBK, Killer Bee and Rorschach opened. This atlas''s census took it for a separate house."}]' WHERE `name` = 'Black Label Trading Co.';
UPDATE `brands` SET `gamme_es` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","wrapper":"Ligada Oveja Negra","vitolas":["Robusto","Toro","Petit Lancero"],"story":"«Los últimos sacramentos»: la gama fundadora, y la que dio el tono a toda la iconografía de la casa. Fuerte, liada en la Oveja Negra."},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","wrapper":"Ligada Oveja Negra","vitolas":["Robusto","Toro"],"story":"El contrapunto del Last Rites, en el mismo registro litúrgico. Hojas de Nicaragua, Honduras, San Andrés y Ecuador."},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","wrapper":"Ligada Oveja Negra","vitolas":["Robusto","Toro"],"story":"La Santa Muerte de la devoción popular mexicana, dibujada por el propio James Brown. La casa lleva su imaginería hasta el final en vez de solo sugerirla."},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","wrapper":"Habano de Ecuador","vitolas":[],"story":"El segundo nombre de James Brown, noviembre de 2015, misma fábrica — Oveja Negra — para las ligadas menos ortodoxas. NBK, Killer Bee y Rorschach abrieron. El censo de este atlas lo tomaba por una casa aparte."}]' WHERE `name` = 'Black Label Trading Co.';
UPDATE `brands` SET `gamme_de` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","wrapper":"Oveja-Negra-Mischung","vitolas":["Robusto","Toro","Petit Lancero"],"story":"\\"Die Sterbesakramente\\" — die Gründungslinie und diejenige, die den Ton der gesamten Bildsprache des Hauses vorgab. Kräftig, in der Oveja Negra gerollt."},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","wrapper":"Oveja-Negra-Mischung","vitolas":["Robusto","Toro"],"story":"Das Gegenstück zur Last Rites, im selben liturgischen Register. Blätter aus Nicaragua, Honduras, San Andrés und Ecuador."},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","wrapper":"Oveja-Negra-Mischung","vitolas":["Robusto","Toro"],"story":"Der Heilige Tod der mexikanischen Volksfrömmigkeit, von James Brown selbst gezeichnet. Das Haus führt seine Bildsprache zu Ende, statt sie nur anzudeuten."},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"James Browns zweiter Name, November 2015, dieselbe Fabrik — Oveja Negra — für die weniger orthodoxen Blends. NBK, Killer Bee und Rorschach eröffneten. Die Zählung dieses Atlas hielt ihn für ein eigenes Haus."}]' WHERE `name` = 'Black Label Trading Co.';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","wrapper":"Oveja Negra 配方","vitolas":["Robusto","Toro","Petit Lancero"],"story":"「临终圣事」——奠基之作，也为这家的整套图像学定下了基调。浓烈，于 Oveja Negra 卷制。"},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","wrapper":"Oveja Negra 配方","vitolas":["Robusto","Toro"],"story":"Last Rites 的对照款，属同一套礼拜语汇。烟叶来自尼加拉瓜、洪都拉斯、圣安德烈斯与厄瓜多尔。"},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","wrapper":"Oveja Negra 配方","vitolas":["Robusto","Toro"],"story":"墨西哥民间信仰中的「圣死神」，由 James Brown 亲手绘制。这家把自己的图像学做到底，而非仅止于暗示。"},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"詹姆斯·布朗的第二个名字，2015年11月，同一家工厂——Oveja Negra——用于不那么正统的配方。NBK、Killer Bee 与 Rorschach 打头阵。本图集的普查曾把它当作另一家公司。"}]' WHERE `name` = 'Black Label Trading Co.';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","wrapper":"مزيج أوبيخا نيغرا","vitolas":["Robusto","Toro","Petit Lancero"],"story":"«الطقوس الأخيرة» — السلسلة المؤسِّسة، وهي التي أعطت نبرتها لكامل أيقونوغرافيا الدار. قويّة، وملفوفة في أوبيخا نيغرا."},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","wrapper":"مزيج أوبيخا نيغرا","vitolas":["Robusto","Toro"],"story":"نظيرة «لاست رايتس»، في السجلّ الطقسي نفسه. أوراق من نيكاراغوا وهندوراس وسان أندريس والإكوادور."},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","wrapper":"مزيج أوبيخا نيغرا","vitolas":["Robusto","Toro"],"story":"«الموت المقدّس» في التديّن الشعبي المكسيكي، من رسم جيمس براون نفسه. تمضي الدار بصورها إلى منتهاها بدل الاكتفاء بالتلميح."},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","wrapper":"هابانو إكوادوري","vitolas":[],"story":"الاسم الثاني لجيمس براون، تشرين الثاني/نوفمبر 2015، المصنع نفسه — Oveja Negra — للمزجات الأقلّ تقليديةً. افتتحها NBK وKiller Bee وRorschach. وكان إحصاء هذا الأطلس يحسبها دارًا مستقلّة."}]' WHERE `name` = 'Black Label Trading Co.';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : halfwheel.com « Black Label Trading Founder Launches Black Works Studio » et cigar-coop.com (novembre 2015 : James Brown lance Black Works Studio, second projet sorti de la Fábrica Oveja Negra pour les assemblages moins orthodoxes ; NBK, Killer Bee, Rorschach avant la fin 2015)') WHERE `name` = 'Black Label Trading Co.' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── Aganorsa Leaf ──
UPDATE `brands` SET `gamme` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","wrapper":"Corojo 99","vitolas":["Robusto"],"story":"Cent pour cent tabac maison, de la tripe à la cape. C''est l''argument entier de la marque : goûter le terroir de Jalapa sans intermédiaire, en pleine force."},{"name":"Signature Selection","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Toro"],"story":"Le même tabac dans un assemblage plus retenu, où le sucré de la feuille passe devant la puissance. Le meilleur point d''entrée dans le style de la maison."},{"name":"Condega","color":"#6B4226","force":"Medium","wrapper":"Puro nicaraguayen","vitolas":[],"story":"Une marque rachetée en 2002 avec Tropical Tobacco, achetée à Pedro Martín — le nom d''une ville et d''un terroir entre Estelí et Jalapa. Le recensement de cet atlas la prenait pour une maison."}]' WHERE `name` = 'Aganorsa Leaf';
UPDATE `brands` SET `gamme_en` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","wrapper":"Corojo 99","vitolas":["Robusto"],"story":"One hundred per cent house tobacco, from filler to wrapper. That is the whole argument of the brand: to taste the Jalapa terroir without an intermediary, at full strength."},{"name":"Signature Selection","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Toro"],"story":"The same tobacco in a more restrained blend, where the sweetness of the leaf comes ahead of the power. The best way into the style of the house."},{"name":"Condega","color":"#6B4226","force":"Medium","wrapper":"Nicaraguan puro","vitolas":[],"story":"A brand bought in 2002 with Tropical Tobacco, purchased from Pedro Martín — the name of a town and a terroir between Estelí and Jalapa. This atlas''s census took it for a house."}]' WHERE `name` = 'Aganorsa Leaf';
UPDATE `brands` SET `gamme_es` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","wrapper":"Corojo 99","vitolas":["Robusto"],"story":"Cien por cien tabaco de la casa, de la tripa a la capa. Ese es el argumento entero de la marca: probar el terruño de Jalapa sin intermediario, a plena fuerza."},{"name":"Signature Selection","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Toro"],"story":"El mismo tabaco en una liga más contenida, donde el dulzor de la hoja pasa por delante de la potencia. La mejor puerta de entrada al estilo de la casa."},{"name":"Condega","color":"#6B4226","force":"Medium","wrapper":"Puro nicaragüense","vitolas":[],"story":"Una marca comprada en 2002 con Tropical Tobacco, adquirida a Pedro Martín — el nombre de un pueblo y de un terruño entre Estelí y Jalapa. El censo de este atlas la tomaba por una casa."}]' WHERE `name` = 'Aganorsa Leaf';
UPDATE `brands` SET `gamme_de` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","wrapper":"Corojo 99","vitolas":["Robusto"],"story":"Hundert Prozent hauseigener Tabak, von der Einlage bis zum Deckblatt. Das ist das ganze Argument der Marke: das Terroir von Jalapa ohne Zwischenhändler schmecken, in voller Kraft."},{"name":"Signature Selection","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Toro"],"story":"Derselbe Tabak in einem zurückhaltenderen Blend, in dem die Süße des Blattes vor der Kraft steht. Der beste Einstieg in den Stil des Hauses."},{"name":"Condega","color":"#6B4226","force":"Medium","wrapper":"Nicaraguanischer Puro","vitolas":[],"story":"Eine Marke, 2002 mit Tropical Tobacco gekauft, erworben von Pedro Martín — der Name einer Stadt und eines Terroirs zwischen Estelí und Jalapa. Die Zählung dieses Atlas hielt sie für ein Haus."}]' WHERE `name` = 'Aganorsa Leaf';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","wrapper":"Corojo 99","vitolas":["Robusto"],"story":"从茄芯到茄衣，百分之百自家烟叶。这就是这个品牌的全部主张：不经中间人，以全力度品尝哈拉帕的风土。"},{"name":"Signature Selection","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Toro"],"story":"同样的烟叶，配方更收敛，烟叶的甜感走在力度之前。进入这家风格的最佳入口。"},{"name":"Condega","color":"#6B4226","force":"Medium","wrapper":"尼加拉瓜纯料","vitolas":[],"story":"2002年随 Tropical Tobacco 从佩德罗·马丁手中买下的品牌——一个介于埃斯特利与哈拉帕之间的城镇与产区之名。本图集的普查曾把它当作一家公司。"}]' WHERE `name` = 'Aganorsa Leaf';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","wrapper":"Corojo 99","vitolas":["Robusto"],"story":"تبغ الدار مئة في المئة، من الحشوة إلى الغلاف. وهذه حجّة العلامة كاملةً: تذوّق أرض خالابا دون وسيط، وبكامل القوّة."},{"name":"Signature Selection","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Toro"],"story":"التبغ نفسه في خلطة أكثر تحفّظاً، تتقدّم فيها حلاوة الورقة على القوّة. وهو أفضل مدخل إلى أسلوب الدار."},{"name":"Condega","color":"#6B4226","force":"Medium","wrapper":"نيكاراغوي خالص","vitolas":[],"story":"علامةٌ اشتُريت سنة 2002 مع Tropical Tobacco من بيدرو مارتين — اسم بلدة وأرضٍ بين إستيلي وخالابا. وكان إحصاء هذا الأطلس يحسبها دارًا."}]' WHERE `name` = 'Aganorsa Leaf';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : cigarinspector.com « The history of Condega Cigars » et cigaraficionado.com « The Aganorsa Enigma » (Condega rachetée en 2002 par Eduardo Fernández avec Tropical Tobacco, achetée à Pedro Martín ; la maison a porté le nom de Casa Fernández avant Aganorsa Leaf)') WHERE `name` = 'Aganorsa Leaf' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── J.C. Newman ──
UPDATE `brands` SET `gamme` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","wrapper":"Habano d''Équateur","vitolas":[],"story":"Un nom de la maison des années 1930, relancé. Roulée à PENSA, la fabrique de la famille à Estelí, où elle a été rapatriée d''une autre fabrique."},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","wrapper":"Connecticut d''Équateur","vitolas":[],"story":"La perle de la mer — une ligne de PENSA, ajoutée peu après l''ouverture de 2011."},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","wrapper":"Non divulguée","vitolas":[],"story":"L''un des deux cigares avec lesquels PENSA a ouvert en 2011, avec El Baton. Le cigare de volume de la fabrique."}]' WHERE `name` = 'J.C. Newman';
UPDATE `brands` SET `gamme_en` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"A house name of the 1930s, revived. Rolled at PENSA, the family''s factory in Estelí, where it was brought back from another factory."},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","wrapper":"Ecuadorian Connecticut","vitolas":[],"story":"The pearl of the sea — a PENSA line, added shortly after the 2011 opening."},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","wrapper":"Undisclosed","vitolas":[],"story":"One of the two cigars with which PENSA opened in 2011, with El Baton. The factory''s volume cigar."}]' WHERE `name` = 'J.C. Newman';
UPDATE `brands` SET `gamme_es` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","wrapper":"Habano de Ecuador","vitolas":[],"story":"Un nombre de la casa de los años 1930, relanzado. Liada en PENSA, la fábrica de la familia en Estelí, adonde fue repatriada desde otra fábrica."},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","wrapper":"Connecticut de Ecuador","vitolas":[],"story":"La perla del mar — una línea de PENSA, añadida poco después de la apertura de 2011."},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","wrapper":"No divulgada","vitolas":[],"story":"Uno de los dos puros con los que PENSA abrió en 2011, con El Baton. El puro de volumen de la fábrica."}]' WHERE `name` = 'J.C. Newman';
UPDATE `brands` SET `gamme_de` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"Ein Hausname der 1930er, wiederbelebt. Bei PENSA gerollt, der Fabrik der Familie in Estelí, wohin sie aus einer anderen Fabrik zurückgeholt wurde."},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","wrapper":"Ecuadorianisches Connecticut","vitolas":[],"story":"Die Perle des Meeres — eine PENSA-Linie, kurz nach der Eröffnung 2011 hinzugefügt."},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Eine der beiden Zigarren, mit denen PENSA 2011 eröffnete, mit El Baton. Die Mengenzigarre der Fabrik."}]' WHERE `name` = 'J.C. Newman';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"家族1930年代的一个旧名，重新启用。在家族位于埃斯特利的 PENSA 厂卷制，是从另一家工厂迁回来的。"},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","wrapper":"厄瓜多尔康涅狄格","vitolas":[],"story":"海之珍珠——PENSA 的一条线，在2011年开厂后不久加入。"},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","wrapper":"未公开","vitolas":[],"story":"PENSA 2011年开厂时的两支雪茄之一，另一支是 El Baton。工厂的走量雪茄。"}]' WHERE `name` = 'J.C. Newman';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","wrapper":"هابانو إكوادوري","vitolas":[],"story":"اسمٌ من أسماء الدار في الثلاثينيات، أُعيد إحياؤه. تُلفّ في PENSA، مصنع العائلة في إستيلي، حيث أُعيدت من مصنع آخر."},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","wrapper":"كونيتيكت إكوادوري","vitolas":[],"story":"لؤلؤة البحر — خطّ من PENSA، أُضيف بُعيد افتتاح 2011."},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","wrapper":"غير معلن","vitolas":[],"story":"أحد السيجارين اللذين افتتحت بهما PENSA سنة 2011، مع El Baton. سيجار الكمّية في المصنع."}]' WHERE `name` = 'J.C. Newman';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : halfwheel.com « J.C. Newman Renames PENSA Factory » (25 avril 2018 : PENSA — Puros de Estelí Nicaragua S.A. — ouverte en 2011 avec Quorum et El Baton, puis Perla del Mar, puis Brick House rapatriée d''une autre fabrique ; plus de 100 000 cigares par jour ; co-dirigée par Omar Ortez et Lázaro López) ; cigaraficionado.com « J.C. Newman Opens Nicaraguan Cigar Factory »') WHERE `name` = 'J.C. Newman' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── La Aurora ──
UPDATE `brands` SET `gamme` = '[{"name":"1903 Preferidos","color":"#8B4513","force":"Medium","wrapper":"Cameroun","vitolas":["Figurado"],"story":"La série qui porte l''année de fondation, et la cape cameroun qui est la signature de la maison : bois épicé, noisette grillée, cuir clair. Un figurado, forme que La Aurora roule depuis longtemps."},{"name":"107","color":"#A0522D","force":"Medium","wrapper":"Habano Ecuador","vitolas":["Robusto"],"story":"Une série anniversaire devenue permanente. Plus contemporaine que la 1903, plus ronde, et pensée pour ceux qui découvrent la maison."},{"name":"León Jimenes","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Connecticut d''Équateur","vitolas":[],"story":"Le nom du fondateur, Eduardo León Jimenes, sur une ligne de la maison. Le recensement de cet atlas la prenait pour une marque à part."}]' WHERE `name` = 'La Aurora';
UPDATE `brands` SET `gamme_en` = '[{"name":"1903 Preferidos","color":"#8B4513","force":"Medium","wrapper":"Cameroon","vitolas":["Figurado"],"story":"The series that carries the founding year, and the Cameroon wrapper that is the signature of the house: spiced wood, toasted hazelnut, pale leather. A figurado, a shape La Aurora has rolled for a long time."},{"name":"107","color":"#A0522D","force":"Medium","wrapper":"Ecuadorian Habano","vitolas":["Robusto"],"story":"An anniversary series turned permanent. More contemporary than the 1903, rounder, and meant for those discovering the house."},{"name":"León Jimenes","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Ecuadorian Connecticut","vitolas":[],"story":"The founder''s name, Eduardo León Jimenes, on a line of the house. This atlas''s census took it for a separate brand."}]' WHERE `name` = 'La Aurora';
UPDATE `brands` SET `gamme_es` = '[{"name":"1903 Preferidos","color":"#8B4513","force":"Medium","wrapper":"Camerún","vitolas":["Figurado"],"story":"La serie que lleva el año de fundación, y la capa de Camerún que es la firma de la casa: madera especiada, avellana tostada, cuero claro. Un figurado, forma que La Aurora lía desde hace mucho."},{"name":"107","color":"#A0522D","force":"Medium","wrapper":"Habano de Ecuador","vitolas":["Robusto"],"story":"Una serie de aniversario convertida en permanente. Más contemporánea que la 1903, más redonda, y pensada para quienes descubren la casa."},{"name":"León Jimenes","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Connecticut de Ecuador","vitolas":[],"story":"El nombre del fundador, Eduardo León Jimenes, en una línea de la casa. El censo de este atlas la tomaba por una marca aparte."}]' WHERE `name` = 'La Aurora';
UPDATE `brands` SET `gamme_de` = '[{"name":"1903 Preferidos","color":"#8B4513","force":"Medium","wrapper":"Kamerun","vitolas":["Figurado"],"story":"Die Serie, die das Gründungsjahr trägt, und das Kamerun-Deckblatt, das die Handschrift des Hauses ist: würziges Holz, geröstete Haselnuss, helles Leder. Ein Figurado — eine Form, die La Aurora seit Langem rollt."},{"name":"107","color":"#A0522D","force":"Medium","wrapper":"Habano aus Ecuador","vitolas":["Robusto"],"story":"Eine Jubiläumsserie, die dauerhaft wurde. Zeitgenössischer als die 1903, runder, und für jene gedacht, die das Haus entdecken."},{"name":"León Jimenes","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Ecuadorianisches Connecticut","vitolas":[],"story":"Der Name des Gründers, Eduardo León Jimenes, auf einer Linie des Hauses. Die Zählung dieses Atlas hielt sie für eine eigene Marke."}]' WHERE `name` = 'La Aurora';
UPDATE `brands` SET `gamme_zh` = '[{"name":"1903 Preferidos","color":"#8B4513","force":"Medium","wrapper":"喀麦隆","vitolas":["Figurado"],"story":"以创立年份命名的系列，配上作为这家签名的喀麦隆茄衣：香料木质、烤榛子、浅色皮革。一支异形茄——这是极光长久以来卷制的形制。"},{"name":"107","color":"#A0522D","force":"Medium","wrapper":"厄瓜多尔哈瓦那种","vitolas":["Robusto"],"story":"一个由纪念系列转为常规的产品。比1903更当代、更圆润，是为初识这家的人而设。"},{"name":"León Jimenes","color":"#8B5A2B","force":"Mild-Medium","wrapper":"厄瓜多尔康涅狄格","vitolas":[],"story":"创始人爱德华多·莱昂·希梅内斯的名字，用于公司的一条线。本图集的普查曾把它当作独立品牌。"}]' WHERE `name` = 'La Aurora';
UPDATE `brands` SET `gamme_ar` = '[{"name":"1903 Preferidos","color":"#8B4513","force":"Medium","wrapper":"كاميرون","vitolas":["Figurado"],"story":"السلسلة التي تحمل سنة التأسيس، والغلاف الكاميروني الذي هو توقيع الدار: خشب متبَّل وبندق محمّص وجلد فاتح. «فيغورادو»، وهو شكل تلفّه «لا أورورا» منذ زمن بعيد."},{"name":"107","color":"#A0522D","force":"Medium","wrapper":"هابانو إكوادوري","vitolas":["Robusto"],"story":"سلسلة تذكارية صارت دائمة. أكثر معاصرة من «1903» وأكثر استدارة، ومصمَّمة لمن يكتشف الدار حديثاً."},{"name":"León Jimenes","color":"#8B5A2B","force":"Mild-Medium","wrapper":"كونيتيكت إكوادوري","vitolas":[],"story":"اسم المؤسّس، إدواردو ليون خيمينيس، على خطّ من خطوط الدار. وكان إحصاء هذا الأطلس يحسبه علامة مستقلّة."}]' WHERE `name` = 'La Aurora';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : laaurora.com.do (León Jimenes, ligne au nom du fondateur Eduardo León Jimenes)') WHERE `name` = 'La Aurora' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── Drew Estate ──
UPDATE `brands` SET `gamme` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"La gamme infusée qui a fait connaître la maison — arômes de thé, herbes botaniques, essence florale. Format Robusto (54 x 127mm). Cape d''Indonésie sur un assemblage que Drew Estate ne détaille pas. C''est le cigare qui a fait entrer dans le genre des fumeurs que la puissance des assemblages traditionnels aurait écartés. Contesté chez les puristes, adoré de ses amateurs.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonésie"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"L''autre visage de Drew Estate — le plus sérieux, le plus recherché. Cape Connecticut Broadleaf Habano sur triple ligero nicaraguayen. Notes de café ristretto, cacao amer, mûre. La Flying Pig, perfecto court et trapu, est le format le plus rare et le plus cher de la gamme.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Créée par les torcedores eux-mêmes — les ouvriers de l''usine voulaient un cigare aussi bon que la Liga Privada à un prix qu''ils pouvaient payer. Assemblage proche du No.9, sous une cape d''Équateur moins coûteuse. Notes de chocolat, café, poivre.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Équateur"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"Habano d''Équateur","vitolas":[],"story":"Le cigare de Willy Herrera, l''assembleur d''El Titan de Bronze à Miami engagé en 2011, lancé au début de 2013 sur une recette composée lors de sa première visite à Estelí. Le recensement de cet atlas le prenait pour une maison."},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"Kentucky séché au feu","vitolas":[],"story":"Du tabac de Kentucky séché à la fumée de bois, comme celui des pipes, dans un cigare roulé à Estelí. Une ligne, pas une maison."}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `gamme_en` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"The infused best-seller — aromas of tea, botanical herbs, floral essence. Robusto format (54 x 127mm). The cigar that introduced millions of Americans to cigars without intimidating them with traditional blend power. Indonesian wrapper over Drew Estate proprietary blend. Controversial among purists, adored by fans.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesian"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"The other face of Drew Estate — the most serious, the most sought after. Connecticut Broadleaf Habano wrapper over Nicaraguan triple ligero. Ristretto coffee, bitter cocoa, blackberry. The Flying Pig, a short stubby perfecto, is the rarest and dearest shape in the range.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Created by the torcedores themselves — factory workers who wanted a cigar as good as Liga Privada at an accessible price. Blend close to the No.9, less expensive Ecuadorian wrapper. Notes of chocolate, coffee, pepper. The most successful worker rebellion in the industry.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuadorian"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"Ecuadorian Habano","vitolas":[],"story":"Willy Herrera''s cigar — the El Titan de Bronze blender from Miami, hired in 2011 — launched in early 2013 on a recipe composed during his first visit to Estelí. This atlas''s census took it for a house."},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"Fire-cured Kentucky","vitolas":[],"story":"Kentucky tobacco cured over wood smoke, as for pipes, in a cigar rolled in Estelí. A line, not a house."}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `gamme_es` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"El superventas infusionado: aromas de té, hierbas botánicas, esencia floral. Robusto (54 x 127mm). El puro que introdujo a millones de estadounidenses en el cigarro sin asustarlos con la potencia de las ligas tradicionales. Capa indonesia sobre liga propia de Drew Estate. Controvertido entre los puristas, adorado por sus fieles.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesia"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"La otra cara de Drew Estate: la más seria, la más buscada. Capa Connecticut Broadleaf Habano sobre triple ligero nicaragüense. Café ristretto, cacao amargo, mora. La Flying Pig, un perfecto corto y rechoncho, es el formato más raro y más caro de la gama.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Creada por los propios torcedores: los obreros de la fábrica querían un puro tan bueno como Liga Privada a precio accesible. Liga cercana a la del No.9, capa ecuatoriana más económica. Chocolate, café, pimienta. La revuelta obrera más lograda del sector.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuador"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"Habano de Ecuador","vitolas":[],"story":"El puro de Willy Herrera, el ligador de El Titan de Bronze en Miami contratado en 2011, lanzado a principios de 2013 con una receta compuesta en su primera visita a Estelí. El censo de este atlas lo tomaba por una casa."},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"Kentucky curado al fuego","vitolas":[],"story":"Tabaco de Kentucky curado al humo de leña, como el de las pipas, en un puro liado en Estelí. Una línea, no una casa."}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `gamme_de` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"Der infundierte Bestseller — Tee, botanische Kräuter, blumige Essenz. Robusto (54 x 127 mm). Die Zigarre, die Millionen Amerikaner an die Zigarre heranführte, ohne sie mit der Kraft traditioneller Mischungen zu erschrecken. Indonesisches Deckblatt über hauseigener Drew-Estate-Mischung. Umstritten bei Puristen, geliebt von ihren Anhängern.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesien"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"Das andere Gesicht von Drew Estate — das ernsteste, das begehrteste. Deckblatt Connecticut Broadleaf Habano über nicaraguanischem Triple Ligero. Ristretto, bittere Kakao, Brombeere. Die Flying Pig, ein kurzes, gedrungenes Perfecto, ist das seltenste und teuerste Format der Serie.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Von den Torcedores selbst geschaffen — die Arbeiter der Fabrik wollten eine Zigarre so gut wie die Liga Privada zu zugänglichem Preis. Mischung nah am No.9, günstigeres ecuadorianisches Deckblatt. Schokolade, Kaffee, Pfeffer. Die gelungenste Arbeiterrevolte der Branche.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuador"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"Die Zigarre von Willy Herrera, dem 2011 engagierten Blender von El Titan de Bronze in Miami, Anfang 2013 lanciert nach einem Rezept aus seinem ersten Besuch in Estelí. Die Zählung dieses Atlas hielt sie für ein Haus."},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"Feuergetrockneter Kentucky","vitolas":[],"story":"Kentucky-Tabak, über Holzrauch getrocknet wie für Pfeifen, in einer in Estelí gerollten Zigarre. Eine Linie, kein Haus."}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `gamme_zh` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"浸香系列的畅销之作——茶、植物香草、花香精油。罗布图规格（54 x 127 毫米）。正是这支雪茄让数百万美国人接触雪茄，而不必先被传统配方的力度吓退。印尼茄衣，内裹 Drew Estate 自有配方。纯粹派对它争议不断，拥趸却爱之如命。","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"印尼"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"Drew Estate 的另一副面孔——最正经，也最抢手。康涅狄格宽叶哈瓦那茄衣，内裹尼加拉瓜三重利赫罗。里斯特雷托咖啡、苦可可、黑莓。短而粗壮的 Flying Pig 是全系中最稀有也最昂贵的规格。","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"由卷制师们自己创制——厂里的工人想要一支像 Liga Privada 一样好、价格却够得着的雪茄。配方接近 No.9，改用更便宜的厄瓜多尔茄衣。巧克力、咖啡、胡椒。这是行业里最成功的一场工人起义。","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"厄瓜多尔"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"威利·埃雷拉的雪茄——他是迈阿密 El Titan de Bronze 的调配师，2011年受聘——2013年初推出，配方在他首次造访埃斯特利时调成。本图集的普查曾把它当作一家公司。"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"烟熏干燥的肯塔基烟叶","vitolas":[],"story":"像烟斗烟草那样用木柴烟熏干燥的肯塔基烟叶，卷进一支埃斯特利制作的雪茄。是一条线，不是一家公司。"}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `gamme_ar` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"الأكثر مبيعًا بين المنقوعات — شاي، أعشاب نباتية، خلاصة زهرية. روبوستو (54 × 127 مم). السيجار الذي عرّف ملايين الأمريكيين على التدخين دون أن يُفزعهم بقوّة الخلطات التقليدية. غلاف إندونيسي فوق خلطة خاصة بـDrew Estate. مثير للجدل عند المتشدّدين، محبوب عند أنصاره.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"إندونيسي"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"الوجه الآخر لـDrew Estate — الأكثر جدّية والأكثر طلبًا. غلاف كونيتيكت برودليف هابانو فوق ليغيرو نيكاراغوي ثلاثي. قهوة ريستريتو، كاكاو مرّ، توت أسود. أما الـFlying Pig، وهو بيرفيكتو قصير ممتلئ، فأندر قياسات المجموعة وأغلاها.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"أنشأها اللافّون أنفسهم — أراد عمّال المصنع سيجارًا بجودة الليغا بريفادا وبسعر في المتناول. خلطة قريبة من الـNo.9، بغلاف إكوادوري أقلّ كلفة. شوكولاتة، قهوة، فلفل. أنجح ثورة عمالية في هذه الصناعة.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"إكوادوري"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"هابانو إكوادوري","vitolas":[],"story":"سيجار ويلي إيريرا، مزّاج El Titan de Bronze في ميامي الذي استُقدم سنة 2011، أُطلق في مطلع 2013 على وصفة رُكّبت في زيارته الأولى لإستيلي. وكان إحصاء هذا الأطلس يحسبه دارًا."},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"كنتاكي مجفَّف بالنار","vitolas":[],"story":"تبغ كنتاكي مجفَّف على دخان الخشب كتبغ الغليون، في سيجار يُلفّ في إستيلي. خطٌّ لا دار."}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : cigaraficionado.com « Willy Herrera Named Master Blender of Drew Estate » et halfwheel.com « Herrera Esteli Toro Especial » (Willy Herrera, assembleur d''El Titan de Bronze à Miami, engagé en 2011 ; Herrera Estelí lancée début 2013 sur un assemblage composé lors de sa première visite en 2010) ; drewestate.com (Kentucky Fire Cured)') WHERE `name` = 'Drew Estate' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── Rocky Patel ──
UPDATE `brands` SET `gamme` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"Le nom renvoie à l''origine des capes du premier assemblage, récoltées en 1992 — pas à l''âge du tabac vendu aujourd''hui. Cape Ecuador Connecticut sur tabacs honduriens et nicaraguayens. Notes de noisette grillée, caramel, bois clair. Mi-corsée à corsée, équilibrée ; la série Vintage reste l''une des propositions les plus narratives du marché : chaque millésime raconte une récolte.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Lancée pour les 50 ans de Rocky Patel — l''homme, pas la marque. Assemblage hondurien-nicaraguayen complexe, cape d''Équateur cultivée en plein soleil. Notes de café, épices orientales, sous-bois. Format Toro, 50 x 152mm. Une gamme qui reste dans l''ombre des séries Vintage alors qu''elle en dit autant sur la maison.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Plein soleil d''Équateur"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"La gamme accessible de la maison. Formats Robusto et Toro, cape Connecticut, tabacs hondurien et nicaraguayen. Notes douces de crème et de noisette. Le premier Rocky Patel pour un néophyte — facile d''approche, régulier, gratifiant. Prix démocratique.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Les cigares d''Hamlet Paredes, ancien rouleur de Partagás et ambassadeur d''Habanos, engagé en 2015 — Tabaquero d''abord, puis Liberation et 25th Year. Paredes est parti en août 2022 ; la maison garde le nom et les lignes, et a arrêté Tabaquero."}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `gamme_en` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"The name refers to the origin of the wrappers used in the first blend, harvested in 1992 — not to the age of the tobacco sold today. Ecuador Connecticut wrapper over Honduran and Nicaraguan leaf. Toasted hazelnut, caramel, pale wood. A balanced medium-full, and the Vintage series remains one of the most narrative propositions on the market: each vintage tells of a harvest.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Launched for Rocky Patel''s fiftieth birthday — the man, not the brand. A complex Honduran-Nicaraguan blend, Ecuadorian wrapper grown in full sun. Coffee, oriental spice, forest floor. Toro format, 50 x 152mm. A range that stays in the shadow of the Vintage series though it says just as much about the house.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Ecuadorian Sun-Grown"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"The house''s accessible range. Robusto and Toro formats, Connecticut wrapper, Honduran and Nicaraguan leaf. Gentle cream and hazelnut. The first Rocky Patel for a newcomer — easy to approach, consistent, rewarding. A democratic price.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"The cigars of Hamlet Paredes, former Partagás roller and Habanos ambassador, hired in 2015 — Tabaquero first, then Liberation and 25th Year. Paredes left in August 2022; the house keeps the name and the lines, and discontinued Tabaquero."}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `gamme_es` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"El nombre remite al origen de las capas del primer ligado, cosechadas en 1992, no a la edad del tabaco que se vende hoy. Capa Ecuador Connecticut sobre tabacos hondureños y nicaragüenses. Avellana tostada, caramelo, madera clara. Un medio-fuerte equilibrado, y la serie Vintage sigue siendo una de las propuestas más narrativas del mercado: cada añada cuenta una cosecha.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Lanzada por los 50 años de Rocky Patel, el hombre, no la marca. Ligado hondureño-nicaragüense complejo, capa ecuatoriana cultivada a pleno sol. Café, especias orientales, sotobosque. Formato Toro, 50 x 152mm. Una gama que permanece a la sombra de las series Vintage aunque diga otro tanto sobre la casa.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"De sol de Ecuador"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"La gama accesible de la casa. Formatos Robusto y Toro, capa Connecticut, tabacos hondureño y nicaragüense. Notas suaves de crema y avellana. El primer Rocky Patel para un neófito: fácil de abordar, regular, gratificante. Precio democrático.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (México)","vitolas":[],"story":"Los puros de Hamlet Paredes, antiguo torcedor de Partagás y embajador de Habanos, contratado en 2015 — Tabaquero primero, luego Liberation y 25th Year. Paredes se fue en agosto de 2022; la casa conserva el nombre y las líneas, y retiró Tabaquero."}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `gamme_de` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"Der Name verweist auf die Herkunft der Deckblätter der ersten Mischung, geerntet 1992 — nicht auf das Alter des heute verkauften Tabaks. Deckblatt Ecuador Connecticut über honduranischem und nicaraguanischem Tabak. Geröstete Haselnuss, Karamell, helles Holz. Ein ausgewogenes Medium-Full, und die Vintage-Serie bleibt eines der erzählerischsten Angebote des Marktes: Jeder Jahrgang erzählt von einer Ernte.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Zum 50. Geburtstag von Rocky Patel lanciert — dem Mann, nicht der Marke. Komplexe honduranisch-nicaraguanische Mischung, ecuadorianisches Deckblatt aus vollem Sonnenanbau. Kaffee, orientalische Gewürze, Waldboden. Format Toro, 50 x 152 mm. Eine Serie, die im Schatten der Vintage-Reihen bleibt, obwohl sie ebenso viel über das Haus erzählt.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Sonnenanbau aus Ecuador"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"Die zugängliche Serie des Hauses. Formate Robusto und Toro, Deckblatt Connecticut, honduranischer und nicaraguanischer Tabak. Milde Noten von Sahne und Haselnuss. Der erste Rocky Patel für Einsteiger — leicht zugänglich, gleichmäßig, dankbar. Ein demokratischer Preis.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Die Zigarren von Hamlet Paredes, ehemaligem Partagás-Roller und Habanos-Botschafter, 2015 engagiert — zuerst Tabaquero, dann Liberation und 25th Year. Paredes ging im August 2022; das Haus behält Namen und Linien und stellte Tabaquero ein."}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"名字指的是首款配方所用茄衣的来历——那批茄衣收于 1992 年，而不是今天所售烟叶的年份。厄瓜多尔康涅狄格茄衣，包裹洪都拉斯与尼加拉瓜烟叶。烤榛子、焦糖、浅色木。中偏浓而均衡；Vintage 系列至今仍是市场上最有叙事性的构想之一：每一个年份都在讲一次收成。","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"为洛基·帕特尔五十岁而推出——是这个人，不是这个牌子。复杂的洪都拉斯－尼加拉瓜配方，茄衣来自厄瓜多尔的全日照种植。咖啡、东方香料、林下腐叶。Toro 规格，50 x 152 毫米。这个系列一直被 Vintage 各系列的光芒盖住，可它讲出的老号故事并不更少。","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"厄瓜多尔日光种植"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"这家老号的入门系列。Robusto 与 Toro 两种规格，康涅狄格茄衣，洪都拉斯与尼加拉瓜烟叶。奶油与榛子的柔和气息。给新手的第一支洛基·帕特尔——好上手、稳定、有回报。价格亲民。","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"圣安德烈斯（墨西哥）","vitolas":[],"story":"哈姆雷特·帕雷德斯的雪茄——他曾是 Partagás 的卷工与 Habanos 的大使，2015年受聘——先是 Tabaquero，再是 Liberation 与 25th Year。帕雷德斯2022年8月离开；公司保留名字与各线，停掉了 Tabaquero。"}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"يشير الاسم إلى أصل أغلفة الخلطة الأولى، وقد جُنيت عام 1992 — لا إلى عمر التبغ المُباع اليوم. غلاف إكوادور كونيتيكت فوق تبغ هندوراسي ونيكاراغوي. بندق محمّص، كراميل، خشب فاتح. قوّة متوسطة-عالية متوازنة، وتبقى سلسلة Vintage من أكثر الطروحات سرديّة في السوق: كل سنة تروي حصادًا.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"أُطلقت في عيد ميلاد روكي باتيل الخمسين — الرجل لا العلامة. خلطة هندوراسية-نيكاراغوية معقّدة، وغلاف إكوادوري مزروع في الشمس الكاملة. قهوة، توابل شرقية، أرض غابة. قياس تورو، 50 × 152 مم. مجموعة تبقى في ظلّ سلاسل Vintage، مع أنها تقول عن الدار قدر ما تقوله تلك.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"مزروع في الشمس من الإكوادور"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"المجموعة السهلة لدى الدار. قياسا روبوستو وتورو، غلاف كونيتيكت، وتبغ هندوراسي ونيكاراغوي. نفحات ناعمة من القشدة والبندق. أول روكي باتيل للمبتدئ — سهل التناول، ثابت، مُجزٍ. وسعره في متناول الجميع.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"سان أندريس (المكسيك)","vitolas":[],"story":"سيجارات هاملت باريديس، لفّاف Partagás السابق وسفير Habanos، الذي استُقدم سنة 2015 — Tabaquero أوّلًا، ثم Liberation و25th Year. غادر باريديس في آب/أغسطس 2022؛ وتحتفظ الدار بالاسم والخطوط، وأوقفت Tabaquero."}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : cigaraficionado.com « Hamlet Paredes Departs Rocky Patel » (12 septembre 2022 : Hamlet Paredes, ancien rouleur de Partagás et ambassadeur d''Habanos, engagé en 2015 ; Tabaquero, sa première ligne, la même année ; parti fin août 2022 ; Rocky Patel garde la marque Hamlet — Liberation by Hamlet, Hamlet 25th Year — et arrête Tabaquero)') WHERE `name` = 'Rocky Patel' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── Tatuaje ──
UPDATE `brands` SET `gamme` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"Habano de Ecuador","vitolas":["Robusto","Corona"],"story":"La série d''origine, celle qui porte la marque depuis 2003. Grammaire cubaine, matière nicaraguayenne : poivre, cuir, une combustion lente et régulière qui doit tout au roulage des García."},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"Le registre plus doux de la maison, pensé pour la journée plutôt que pour la soirée. Moins de poivre, plus de bois et de pain grillé."},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut d''Équateur","vitolas":[],"story":"Le versant doux de Pete Johnson — Connecticut d''Équateur sur tabacs nicaraguayens, du nom d''une ville de Cuba. Le recensement de cet atlas la prenait pour une maison."}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `gamme_en` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"Ecuadorian Habano","vitolas":["Robusto","Corona"],"story":"The original line, which has carried the brand since 2003. Cuban grammar, Nicaraguan matter: pepper, leather, and a slow, even burn that owes everything to the Garcías'' rolling."},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"The gentler register of the house, meant for the daytime rather than the evening. Less pepper, more wood and toasted bread."},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"Ecuadorian Connecticut","vitolas":[],"story":"Pete Johnson''s mild side — Ecuadorian Connecticut over Nicaraguan tobaccos, named after a town in Cuba. This atlas''s census took it for a house."}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `gamme_es` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"Habano de Ecuador","vitolas":["Robusto","Corona"],"story":"La serie original, la que lleva la marca desde 2003. Gramática cubana, materia nicaragüense: pimienta, cuero, y una combustión lenta y regular que se lo debe todo al liado de los García."},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"El registro más suave de la casa, pensado para el día antes que para la noche. Menos pimienta, más madera y pan tostado."},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut de Ecuador","vitolas":[],"story":"El lado suave de Pete Johnson — Connecticut de Ecuador sobre tabacos nicaragüenses, con el nombre de un pueblo de Cuba. El censo de este atlas la tomaba por una casa."}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `gamme_de` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"Habano aus Ecuador","vitolas":["Robusto","Corona"],"story":"Die ursprüngliche Serie, die die Marke seit 2003 trägt. Kubanische Grammatik, nicaraguanische Substanz: Pfeffer, Leder und ein langsamer, gleichmäßiger Abbrand, der allein der Rollkunst der Garcías zu verdanken ist."},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"Das sanftere Register des Hauses, eher für den Tag als für den Abend gedacht. Weniger Pfeffer, mehr Holz und Röstbrot."},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"Ecuadorianisches Connecticut","vitolas":[],"story":"Pete Johnsons milde Seite — ecuadorianisches Connecticut über nicaraguanischen Tabaken, nach einer Stadt in Kuba benannt. Die Zählung dieses Atlas hielt sie für ein Haus."}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"厄瓜多尔哈瓦那种","vitolas":["Robusto","Corona"],"story":"最初的系列，自2003年起就代表着这个品牌。古巴的语法，尼加拉瓜的原料：胡椒、皮革，以及缓慢均匀的燃烧——这全要归功于加西亚家族的卷制。"},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"这家更柔和的一面，为白天而非夜晚而设。胡椒更少，木质与烤面包更多。"},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"厄瓜多尔康涅狄格","vitolas":[],"story":"皮特·约翰逊的柔和一面——厄瓜多尔康涅狄格茄衣配尼加拉瓜烟叶，以古巴一座城镇命名。本图集的普查曾把它当作一家公司。"}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"هابانو إكوادوري","vitolas":["Robusto","Corona"],"story":"السلسلة الأصلية التي تحمل العلامة منذ 2003. قواعد كوبية ومادة نيكاراغوية: فلفل وجلد، واحتراق بطيء منتظم يدين بكل شيء للفّ آل غارسيا."},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"الوجه الألطف للدار، مصمَّم للنهار لا للمساء. فلفل أقل، وخشب وخبز محمّص أكثر."},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"كونيتيكت إكوادوري","vitolas":[],"story":"الجانب اللطيف عند بيت جونسون — كونيتيكت إكوادوري على أتبغة نيكاراغوية، باسم بلدة في كوبا. وكان إحصاء هذا الأطلس يحسبها دارًا."}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : tatuajecigars.com (Cabaiguan, cape Connecticut d''Équateur sur tabacs nicaraguayens — la ligne douce de Pete Johnson)') WHERE `name` = 'Tatuaje' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── RoMa Craft Tobac ──
UPDATE `brands` SET `gamme` = '[{"name":"CroMagnon","color":"#4A2C1A","force":"Full","wrapper":"Connecticut Broadleaf maduro","vitolas":["Anthropology","Mandible","EMH"],"story":"La première gamme, née dans le garage d''Esteban Disla en 2010. Cape Connecticut Broadleaf maduro, sous-cape camerounaise, tripe nicaraguayenne."},{"name":"Aquitaine","color":"#8B4513","force":"Full","wrapper":"Habano d''Équateur, ligero","vitolas":["Gran Perfecto","Mode 5","Knuckle Dragger"],"story":"Le pendant de CroMagnon sous une cape de ligero Habano d''Équateur, épaisse et huileuse. Même sous-cape camerounaise, visos et secos de trois fermes nicaraguayennes."},{"name":"Intemperance","color":"#A0522D","force":"Medium","wrapper":"Connecticut d''Équateur (EC XVIII) ou Arapiraca du Brésil (BA XXI)","vitolas":["Virtue","Charity","Justice"],"story":"La gamme la plus abordable, en deux capes au choix. Sous-cape indonésienne, tripes nicaraguayennes et dominicaines — l''assemblage le plus international de la maison."},{"name":"Neanderthal","color":"#2E2018","force":"Full","wrapper":"San Andrés du Mexique","vitolas":["HN","SGP","LH"],"story":"Le plus fort du catalogue. Cape San Andrés, sous-cape Connecticut Broadleaf, tripes de Condega, Estelí, Jalapa et Pueblo Nuevo, un olor ligero dominicain, et un double ligero de Pennsylvanie appelé Green River Sucker One."},{"name":"Baka","color":"#6B4226","force":"Medium-Full","wrapper":"Cameroun","vitolas":[],"story":"2019 — une cape du Cameroun, et le nom d''un peuple des forêts du sud-est de ce pays. Un millier de boîtes par format et par an."}]' WHERE `name` = 'RoMa Craft Tobac';
UPDATE `brands` SET `gamme_en` = '[{"name":"CroMagnon","color":"#4A2C1A","force":"Full","wrapper":"Connecticut Broadleaf maduro","vitolas":["Anthropology","Mandible","EMH"],"story":"The first range, born in Esteban Disla''s garage in 2010. Connecticut Broadleaf maduro wrapper, Cameroon binder, Nicaraguan filler."},{"name":"Aquitaine","color":"#8B4513","force":"Full","wrapper":"Ecuadorian Habano ligero","vitolas":["Gran Perfecto","Mode 5","Knuckle Dragger"],"story":"CroMagnon''s counterpart under a thick, oily Ecuadorian Habano ligero wrapper. Same Cameroon binder, visos and secos from three Nicaraguan farms."},{"name":"Intemperance","color":"#A0522D","force":"Medium","wrapper":"Ecuadorian Connecticut (EC XVIII) or Brazilian Arapiraca (BA XXI)","vitolas":["Virtue","Charity","Justice"],"story":"The most affordable range, in a choice of two wrappers. Indonesian binder, Nicaraguan and Dominican fillers — the house''s most international blend."},{"name":"Neanderthal","color":"#2E2018","force":"Full","wrapper":"Mexican San Andrés","vitolas":["HN","SGP","LH"],"story":"The strongest in the catalogue. San Andrés wrapper, Connecticut Broadleaf binder, fillers from Condega, Estelí, Jalapa and Pueblo Nuevo, a Dominican olor ligero, and a Pennsylvania double ligero called Green River Sucker One."},{"name":"Baka","color":"#6B4226","force":"Medium-Full","wrapper":"Cameroon","vitolas":[],"story":"2019 — a Cameroon wrapper, and the name of a people of the forests of that country''s south-east. A thousand boxes per size per year."}]' WHERE `name` = 'RoMa Craft Tobac';
UPDATE `brands` SET `gamme_es` = '[{"name":"CroMagnon","color":"#4A2C1A","force":"Full","wrapper":"Connecticut Broadleaf maduro","vitolas":["Anthropology","Mandible","EMH"],"story":"La primera gama, nacida en el garaje de Esteban Disla en 2010. Capa Connecticut Broadleaf maduro, capote camerunés, tripa nicaragüense."},{"name":"Aquitaine","color":"#8B4513","force":"Full","wrapper":"Habano de Ecuador, ligero","vitolas":["Gran Perfecto","Mode 5","Knuckle Dragger"],"story":"El contrapunto de CroMagnon bajo una capa de ligero Habano de Ecuador, gruesa y aceitosa. Mismo capote camerunés, visos y secos de tres fincas nicaragüenses."},{"name":"Intemperance","color":"#A0522D","force":"Medium","wrapper":"Connecticut de Ecuador (EC XVIII) o Arapiraca de Brasil (BA XXI)","vitolas":["Virtue","Charity","Justice"],"story":"La gama más asequible, con dos capas a elegir. Capote indonesio, tripas nicaragüenses y dominicanas: la ligada más internacional de la casa."},{"name":"Neanderthal","color":"#2E2018","force":"Full","wrapper":"San Andrés de México","vitolas":["HN","SGP","LH"],"story":"El más fuerte del catálogo. Capa San Andrés, capote Connecticut Broadleaf, tripas de Condega, Estelí, Jalapa y Pueblo Nuevo, un olor ligero dominicano y un doble ligero de Pensilvania llamado Green River Sucker One."},{"name":"Baka","color":"#6B4226","force":"Medium-Full","wrapper":"Camerún","vitolas":[],"story":"2019 — una capa de Camerún, y el nombre de un pueblo de los bosques del sureste de ese país. Un millar de cajas por formato y por año."}]' WHERE `name` = 'RoMa Craft Tobac';
UPDATE `brands` SET `gamme_de` = '[{"name":"CroMagnon","color":"#4A2C1A","force":"Full","wrapper":"Connecticut Broadleaf Maduro","vitolas":["Anthropology","Mandible","EMH"],"story":"Die erste Linie, 2010 in Esteban Dislas Garage entstanden. Deckblatt Connecticut Broadleaf Maduro, Kameruner Umblatt, nicaraguanische Einlage."},{"name":"Aquitaine","color":"#8B4513","force":"Full","wrapper":"Ecuadorianischer Habano-Ligero","vitolas":["Gran Perfecto","Mode 5","Knuckle Dragger"],"story":"Das Gegenstück zur CroMagnon unter einem dicken, öligen Deckblatt aus ecuadorianischem Habano-Ligero. Gleiches Kameruner Umblatt, Visos und Secos von drei nicaraguanischen Farmen."},{"name":"Intemperance","color":"#A0522D","force":"Medium","wrapper":"Ecuador-Connecticut (EC XVIII) oder brasilianisches Arapiraca (BA XXI)","vitolas":["Virtue","Charity","Justice"],"story":"Die günstigste Linie, mit zwei Deckblättern zur Wahl. Indonesisches Umblatt, nicaraguanische und dominikanische Einlagen — die internationalste Mischung des Hauses."},{"name":"Neanderthal","color":"#2E2018","force":"Full","wrapper":"Mexikanisches San Andrés","vitolas":["HN","SGP","LH"],"story":"Die kräftigste des Katalogs. San-Andrés-Deckblatt, Connecticut-Broadleaf-Umblatt, Einlagen aus Condega, Estelí, Jalapa und Pueblo Nuevo, ein dominikanischer Olor-Ligero und ein doppelter Pennsylvania-Ligero namens Green River Sucker One."},{"name":"Baka","color":"#6B4226","force":"Medium-Full","wrapper":"Kamerun","vitolas":[],"story":"2019 — ein Kamerun-Deckblatt und der Name eines Volkes aus den Wäldern im Südosten des Landes. Tausend Kisten pro Format und Jahr."}]' WHERE `name` = 'RoMa Craft Tobac';
UPDATE `brands` SET `gamme_zh` = '[{"name":"CroMagnon","color":"#4A2C1A","force":"Full","wrapper":"康涅狄格宽叶马杜罗","vitolas":["Anthropology","Mandible","EMH"],"story":"最早的一条线，2010 年诞生于 Esteban Disla 的车库。康涅狄格宽叶马杜罗茄衣，喀麦隆茄套，尼加拉瓜茄芯。"},{"name":"Aquitaine","color":"#8B4513","force":"Full","wrapper":"厄瓜多尔 Habano ligero","vitolas":["Gran Perfecto","Mode 5","Knuckle Dragger"],"story":"CroMagnon 的对照款，改用厚实油润的厄瓜多尔 Habano ligero 茄衣。同样的喀麦隆茄套，配三座尼加拉瓜农场的 viso 与 seco。"},{"name":"Intemperance","color":"#A0522D","force":"Medium","wrapper":"厄瓜多尔康涅狄格（EC XVIII）或巴西 Arapiraca（BA XXI）","vitolas":["Virtue","Charity","Justice"],"story":"价位最亲民的一条线，茄衣二选一。印尼茄套，尼加拉瓜与多米尼加茄芯——这家最国际化的配方。"},{"name":"Neanderthal","color":"#2E2018","force":"Full","wrapper":"墨西哥圣安德烈斯","vitolas":["HN","SGP","LH"],"story":"目录中最浓烈的一支。圣安德烈斯茄衣，康涅狄格宽叶茄套，茄芯取自孔德加、埃斯特利、哈拉帕与普韦布洛努埃沃，另有多米尼加 olor ligero 与名为 Green River Sucker One 的宾夕法尼亚双 ligero。"},{"name":"Baka","color":"#6B4226","force":"Medium-Full","wrapper":"喀麦隆","vitolas":[],"story":"2019年——喀麦隆茄衣，以该国东南部森林中的一个民族命名。每种尺寸每年约一千盒。"}]' WHERE `name` = 'RoMa Craft Tobac';
UPDATE `brands` SET `gamme_ar` = '[{"name":"CroMagnon","color":"#4A2C1A","force":"Full","wrapper":"كونيتيكت برودليف مادورو","vitolas":["Anthropology","Mandible","EMH"],"story":"السلسلة الأولى، وُلدت في مرآب إستيبان ديسلا عام 2010. غلاف كونيتيكت برودليف مادورو، ورابط كاميروني، وحشوة نيكاراغوية."},{"name":"Aquitaine","color":"#8B4513","force":"Full","wrapper":"ليغيرو هابانو إكوادوري","vitolas":["Gran Perfecto","Mode 5","Knuckle Dragger"],"story":"نظيرة كرومانيون تحت غلاف من ليغيرو هابانو إكوادوري سميك زيتيّ. الرابط الكاميروني نفسه، مع فيسو وسيكو من ثلاث مزارع نيكاراغوية."},{"name":"Intemperance","color":"#A0522D","force":"Medium","wrapper":"كونيتيكت إكوادوري (EC XVIII) أو أراپيراكا برازيلي (BA XXI)","vitolas":["Virtue","Charity","Justice"],"story":"أيسر السلاسل منالًا، بغلافين للاختيار. رابط إندونيسي، وحشوات نيكاراغوية ودومينيكية — أكثر مزائج الدار عالميّة."},{"name":"Neanderthal","color":"#2E2018","force":"Full","wrapper":"سان أندريس المكسيكي","vitolas":["HN","SGP","LH"],"story":"الأقوى في الكتالوج. غلاف سان أندريس، ورابط كونيتيكت برودليف، وحشوات من كونديغا وإستيلي وخالابا وبويبلو نويفو، وأولور ليغيرو دومينيكي، وليغيرو مزدوج من بنسلفانيا يُدعى Green River Sucker One."},{"name":"Baka","color":"#6B4226","force":"Medium-Full","wrapper":"الكاميرون","vitolas":[],"story":"2019 — غلاف من الكاميرون، واسم شعب من غابات جنوب شرق ذلك البلد. نحو ألف علبة لكلّ قياس في السنة."}]' WHERE `name` = 'RoMa Craft Tobac';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : halfwheel.com « RoMa Craft Tobac Plans Baka for IPCPR 2019 » (Baka, cape du Cameroun, du nom d''un peuple des forêts du sud-est camerounais ; environ mille boîtes par vitole et par an)') WHERE `name` = 'RoMa Craft Tobac' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── A.J. Fernandez ──
UPDATE `brands` SET `gamme` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"L''assemblage qui a fait connaître la maison sous son propre nom. Cape mexicaine sombre, fumée épaisse, notes de café brûlé et de poivre noir — puissant sans être agressif, ce qui est précisément la signature de la maison."},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"Le registre médium de la maison, plus boisé et plus sec. Celui qu''on donne à qui trouve New World trop dense, et qui montre que la force n''a jamais été le sujet."},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"Habano d''Équateur","vitolas":[],"story":"2016 — une ligne de la maison, que le recensement de cet atlas prenait pour une marque à part."},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"Puro nicaraguayen","vitolas":[],"story":"2020 — les jours de gloire : un puro nicaraguayen des fermes de la maison."}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `gamme_en` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"The blend that made the house known under its own name. Dark Mexican wrapper, thick smoke, notes of burnt coffee and black pepper — powerful without being aggressive, which is precisely the signature of the house."},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"The medium register of the house, drier and woodier. The one to hand to anyone who finds New World too dense, and proof that strength was never the point."},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"2016 — a line of the house, which this atlas''s census took for a separate brand."},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"Nicaraguan puro","vitolas":[],"story":"2020 — the days of glory: a Nicaraguan puro from the house''s farms."}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `gamme_es` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"La liga que dio a conocer la casa bajo su propio nombre. Capa mexicana oscura, humo espeso, notas de café tostado y pimienta negra — potente sin ser agresivo, que es precisamente la firma de la casa."},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"El registro medio de la casa, más seco y más amaderado. El que se ofrece a quien encuentra New World demasiado denso, y que demuestra que la fuerza nunca fue el asunto."},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"Habano de Ecuador","vitolas":[],"story":"2016 — una línea de la casa, que el censo de este atlas tomaba por una marca aparte."},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"Puro nicaragüense","vitolas":[],"story":"2020 — los días de gloria: un puro nicaragüense de las fincas de la casa."}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `gamme_de` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"Der Blend, der das Haus unter eigenem Namen bekannt machte. Dunkles mexikanisches Deckblatt, dichter Rauch, Noten von geröstetem Kaffee und schwarzem Pfeffer — kraftvoll, ohne aggressiv zu sein, und genau das ist die Handschrift des Hauses."},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"Das mittlere Register des Hauses, trockener und holziger. Die Zigarre für alle, denen New World zu dicht ist — und der Beweis, dass es nie um Stärke ging."},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"2016 — eine Linie des Hauses, die die Zählung dieses Atlas für eine eigene Marke hielt."},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"Nicaraguanischer Puro","vitolas":[],"story":"2020 — die Tage des Ruhms: ein nicaraguanischer Puro von den Farmen des Hauses."}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `gamme_zh` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"让这家企业以自己名义为人所知的配方。深色墨西哥茄衣，烟雾厚实，带焦咖啡与黑胡椒气息——浓郁而不咄咄逼人，这正是这家企业的签名。"},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"这家企业的中度之作，更干、更偏木质。适合觉得新世界过于厚重的人，也证明力度从来不是重点。"},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"2016年——公司的一条线，本图集的普查曾把它当作独立品牌。"},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"尼加拉瓜纯料","vitolas":[],"story":"2020年——光荣岁月：来自公司自家农场的尼加拉瓜纯料。"}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `gamme_ar` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"الخلطة التي عرّفت بالدار باسمها هي. غلاف مكسيكي داكن، دخان كثيف، ونفحات قهوة محروقة وفلفل أسود — قوّة دون عدوانية، وهذا تحديداً توقيع الدار."},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"المستوى المتوسط للدار، أكثر جفافاً وخشبية. يُقدَّم لمن يجد نيو وورلد ثقيلاً، ويثبت أن القوّة لم تكن يوماً هي الغاية."},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"هابانو إكوادوري","vitolas":[],"story":"2016 — خطّ من خطوط الدار، كان إحصاء هذا الأطلس يحسبه علامة مستقلّة."},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"نيكاراغوي خالص","vitolas":[],"story":"2020 — أيّام المجد: سيجار نيكاراغوي خالص من مزارع الدار."}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : ajfernandezcigars.com (Enclave, cape Habano d''Équateur, 2016 ; Días de Gloria, puro nicaraguayen, 2020)') WHERE `name` = 'A.J. Fernandez' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── Espinosa ──
UPDATE `brands` SET `gamme` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","wrapper":"Cape brésilienne","vitolas":["Toro"],"story":"Une cape brésilienne sur tripe nicaraguayenne — l''une des rares réussites de la feuille de Bahia hors du Brésil. Fruits secs, poivre, une acidité qui vient de la cape."},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","wrapper":"Habano de Nicaragua","vitolas":["Robusto"],"story":"Le style de la maison sans détour : corsé, poivré, franc. Roulé à La Zona, la manufacture que le fondateur a ouverte pour cesser de dépendre des autres."},{"name":"601","color":"#7A2E1E","force":"Full","wrapper":"Habano d''Équateur","vitolas":[],"story":"La ligne née du temps d''EO Brands, gardée par Erik Espinosa après la séparation d''avec Eddie Ortega. Le recensement de cet atlas la prenait pour une marque à part."}]' WHERE `name` = 'Espinosa';
UPDATE `brands` SET `gamme_en` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","wrapper":"Brazilian wrapper","vitolas":["Toro"],"story":"A Brazilian wrapper over Nicaraguan filler — one of the rare successes of the Bahia leaf outside Brazil. Dried fruit, pepper, an acidity that comes from the wrapper."},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","wrapper":"Nicaraguan Habano","vitolas":["Robusto"],"story":"The house style without detours: full-bodied, peppery, frank. Rolled at La Zona, the factory the founder opened to stop depending on others."},{"name":"601","color":"#7A2E1E","force":"Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"The line born in the EO Brands days, kept by Erik Espinosa after the split from Eddie Ortega. This atlas''s census took it for a separate brand."}]' WHERE `name` = 'Espinosa';
UPDATE `brands` SET `gamme_es` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","wrapper":"Capa brasileña","vitolas":["Toro"],"story":"Una capa brasileña sobre tripa nicaragüense — uno de los escasos aciertos de la hoja de Bahía fuera de Brasil. Frutos secos, pimienta, una acidez que viene de la capa."},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","wrapper":"Habano de Nicaragua","vitolas":["Robusto"],"story":"El estilo de la casa sin rodeos: fuerte, apimentado, franco. Liado en La Zona, la fábrica que el fundador abrió para dejar de depender de los demás."},{"name":"601","color":"#7A2E1E","force":"Full","wrapper":"Habano de Ecuador","vitolas":[],"story":"La línea nacida en tiempos de EO Brands, conservada por Erik Espinosa tras la separación de Eddie Ortega. El censo de este atlas la tomaba por una marca aparte."}]' WHERE `name` = 'Espinosa';
UPDATE `brands` SET `gamme_de` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","wrapper":"Brasilianisches Deckblatt","vitolas":["Toro"],"story":"Ein brasilianisches Deckblatt über nicaraguanischer Einlage — einer der seltenen Erfolge des Bahia-Blattes außerhalb Brasiliens. Trockenfrüchte, Pfeffer, eine Säure, die vom Deckblatt kommt."},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","wrapper":"Habano aus Nicaragua","vitolas":["Robusto"],"story":"Der Hausstil ohne Umschweife: kräftig, pfeffrig, offen. Bei La Zona gerollt, der Manufaktur, die der Gründer eröffnete, um nicht länger von anderen abzuhängen."},{"name":"601","color":"#7A2E1E","force":"Full","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"Die Linie aus der Zeit von EO Brands, von Erik Espinosa nach der Trennung von Eddie Ortega behalten. Die Zählung dieses Atlas hielt sie für eine eigene Marke."}]' WHERE `name` = 'Espinosa';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","wrapper":"巴西茄衣","vitolas":["Toro"],"story":"巴西茄衣配尼加拉瓜茄芯——巴伊亚烟叶在巴西之外少见的成功之一。干果、胡椒，以及来自茄衣的一份酸度。"},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","wrapper":"尼加拉瓜哈瓦那种","vitolas":["Robusto"],"story":"不绕弯子的家族风格：浓郁、带胡椒、直率。在「拉索纳」卷制——创始人为不再依赖他人而开设的工厂。"},{"name":"601","color":"#7A2E1E","force":"Full","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"诞生于 EO Brands 时期的系列，与埃迪·奥尔特加分道扬镳后由埃里克·埃斯皮诺萨保留。本图集的普查曾把它当作独立品牌。"}]' WHERE `name` = 'Espinosa';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","wrapper":"غلاف برازيلي","vitolas":["Toro"],"story":"غلاف برازيلي فوق حشوة نيكاراغوية — أحد نجاحات ورقة باهيا النادرة خارج البرازيل. فواكه مجفّفة وفلفل وحموضة تأتي من الغلاف."},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","wrapper":"هابانو نيكاراغوي","vitolas":["Robusto"],"story":"أسلوب الدار بلا التفاف: قويّ، فلفلي، صريح. ملفوف في «لا سونا»، المصنع الذي افتتحه المؤسّس ليكفّ عن الاعتماد على غيره."},{"name":"601","color":"#7A2E1E","force":"Full","wrapper":"هابانو إكوادوري","vitolas":[],"story":"الخطّ الذي وُلد في زمن EO Brands، واحتفظ به إريك إسبينوسا بعد الانفصال عن إدي أورتيغا. وكان إحصاء هذا الأطلس يحسبه علامة مستقلّة."}]' WHERE `name` = 'Espinosa';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : espinosacigars.com (601, la ligne née chez EO Brands, gardée par Erik Espinosa)') WHERE `name` = 'Espinosa' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── Davidoff ──
UPDATE `brands` SET `gamme` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"La gamme fondatrice — Anniversario No.1 et No.2, lancés à Cuba en 1968. Depuis le transfert en République Dominicaine, les Anniversario dominicains sont devenus leur propre référence de finesse. Notes de fleurs blanches, céréales grillées, bois de santal. L''incarnation du luxe sans ostentation.","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"Dominicaine"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"Lancée en 2013, hommage au plus grand fumeur du XXe siècle. Collaboration avec la famille Churchill, autorisation officielle d''utiliser le nom et les archives photographiques. Plus corsée que la gamme classique Davidoff — un virage stylistique majeur. Notes de cuir, bois fumé, épices orientales. La Late Hour est la version nocturne, plus intense encore.","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"Plein soleil d''Équateur"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"Lancée en 2016, rupture stylistique totale. Davidoff explore le tabac nicaraguayen — le plus corsé de son catalogue. Notes de chocolat noir, café, cuir tanné. La gamme Nicaragua démontre que la maison genevoise peut naviguer dans toutes les intensités sans perdre son exigence de régularité.","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"Nicaragua"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"Cape oscuro d''Équateur sur dominicain. La gamme intermédiaire entre la finesse de la Signature et la puissance de la Nicaragua. Notes de noisette, café au lait, épices légères. C''est celle qu''on trouve le plus souvent dans les lounges européens — accessible, régulière, gratifiante.","vitolas":["Robusto","Churchill","Toro"],"wrapper":"Colorado d''Équateur"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","wrapper":"Non divulguée","vitolas":[],"story":"Une marque rachetée en juin 2009 à la famille Chiusano, après Camacho fin 2008 — le groupe achetait un accès au marché américain par le bas de la gamme de prix. Le recensement de cet atlas la prenait pour une maison."}]' WHERE `name` = 'Davidoff';
UPDATE `brands` SET `gamme_en` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"The founding range — Anniversario No.1 and No.2, launched in Cuba in 1968. Since the Dominican transfer, these have become their own reference of finesse. Notes of white flowers, toasted grain, sandalwood. The incarnation of luxury without ostentation.","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"Dominican"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"Launched in 2013, tribute to the greatest smoker of the 20th century. Official collaboration with the Churchill family. Bolder than the classic Davidoff range — a major stylistic shift. Notes of leather, smoky wood, oriental spices. The Late Hour is the nocturnal, even more intense version.","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"Ecuadorian Sun-Grown"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"Launched 2016, total stylistic break. Davidoff explores Nicaraguan tobacco — the boldest in its catalog. Notes of dark chocolate, coffee, tanned leather. The Nicaragua range proves the Geneva house can navigate all intensities without sacrificing its demand for consistency.","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"Nicaraguan"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"Ecuadorian oscuro wrapper over Dominican. The middle range between Signature finesse and Nicaragua power. Notes of hazelnut, café au lait, light spices. The best-seller in European lounges — accessible, consistent, rewarding.","vitolas":["Robusto","Churchill","Toro"],"wrapper":"Ecuadorian Colorado"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","wrapper":"Undisclosed","vitolas":[],"story":"A brand bought in June 2009 from the Chiusano family, after Camacho in late 2008 — the group was buying access to the American market through the low end of the price range. This atlas''s census took it for a house."}]' WHERE `name` = 'Davidoff';
UPDATE `brands` SET `gamme_es` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"La gama fundadora: Anniversario No.1 y No.2, lanzados en Cuba en 1968. Desde el traslado a la República Dominicana, los Anniversario dominicanos se han convertido en su propia referencia de finura. Flores blancas, cereales tostados, sándalo. La encarnación del lujo sin ostentación.","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"Dominicana"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"Lanzada en 2013, homenaje al mayor fumador del siglo XX. Colaboración con la familia Churchill, con autorización oficial para usar el nombre y los archivos fotográficos. Más fuerte que la gama clásica de Davidoff, un giro estilístico mayor. Cuero, madera ahumada, especias orientales. La Late Hour es la versión nocturna, más intensa aún.","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"De sol de Ecuador"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"Lanzada en 2016, ruptura estilística total. Davidoff explora el tabaco nicaragüense, el más fuerte de su catálogo. Chocolate negro, café, cuero curtido. La gama Nicaragua demuestra que la casa ginebrina puede navegar por todas las intensidades sin renunciar a su exigencia de regularidad.","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"Nicaragua"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"Capa oscuro de Ecuador sobre dominicano. La gama intermedia entre la finura de Signature y la potencia de Nicaragua. Avellana, café con leche, especias ligeras. La más vendida en los lounges europeos: accesible, regular, gratificante.","vitolas":["Robusto","Churchill","Toro"],"wrapper":"Colorado de Ecuador"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","wrapper":"No divulgada","vitolas":[],"story":"Una marca comprada en junio de 2009 a la familia Chiusano, tras Camacho a finales de 2008 — el grupo compraba un acceso al mercado estadounidense por la parte baja de los precios. El censo de este atlas la tomaba por una casa."}]' WHERE `name` = 'Davidoff';
UPDATE `brands` SET `gamme_de` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"Die Gründungsserie — Anniversario No.1 und No.2, 1968 auf Kuba lanciert. Seit dem Umzug in die Dominikanische Republik sind die dominikanischen Anniversario zu ihrem eigenen Maßstab an Finesse geworden. Weiße Blüten, geröstetes Getreide, Sandelholz. Die Verkörperung von Luxus ohne Zurschaustellung.","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"Dominikanisch"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"2013 lanciert, eine Hommage an den größten Raucher des 20. Jahrhunderts. Zusammenarbeit mit der Familie Churchill, mit offizieller Erlaubnis zur Nutzung des Namens und der Fotoarchive. Kräftiger als die klassische Davidoff-Serie — eine erhebliche stilistische Wende. Leder, Rauchholz, orientalische Gewürze. Die Late Hour ist die nächtliche, noch intensivere Fassung.","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"Sonnenanbau aus Ecuador"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"2016 lanciert, ein völliger Stilbruch. Davidoff erkundet den nicaraguanischen Tabak — den kräftigsten des Katalogs. Zartbitterschokolade, Kaffee, gegerbtes Leder. Die Nicaragua-Serie zeigt, dass das Genfer Haus alle Intensitäten befahren kann, ohne seinen Anspruch auf Gleichmäßigkeit aufzugeben.","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"Nicaragua"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"Ecuadorianisches Oscuro-Deckblatt über Dominikanischem. Die Serie zwischen der Finesse der Signature und der Kraft der Nicaragua. Haselnuss, Milchkaffee, leichte Gewürze. Die meistverkaufte in europäischen Lounges — zugänglich, gleichmäßig, befriedigend.","vitolas":["Robusto","Churchill","Toro"],"wrapper":"Colorado aus Ecuador"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Eine Marke, im Juni 2009 von der Familie Chiusano gekauft, nach Camacho Ende 2008 — der Konzern kaufte sich Zugang zum amerikanischen Markt über das untere Preissegment. Die Zählung dieses Atlas hielt sie für ein Haus."}]' WHERE `name` = 'Davidoff';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"奠基系列——Anniversario No.1 与 No.2，1968 年在古巴问世。自迁往多米尼加以来，多米尼加版的 Anniversario 已自成细腻的标杆。白花、烤谷物、檀香。这是不事张扬的奢华的化身。","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"多米尼加"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"2013 年推出，向二十世纪最著名的烟客致敬。与丘吉尔家族合作，获正式授权使用其姓名与照片档案。比大卫杜夫的经典系列更浓厚——一次重大的风格转向。皮革、烟熏木、东方香料。Late Hour 是它的夜间版本，更为强烈。","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"厄瓜多尔日光种植"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"2016 年推出，是一次彻底的风格断裂。大卫杜夫转向尼加拉瓜烟叶——其目录中最浓烈的一种。黑巧克力、咖啡、鞣制皮革。Nicaragua 系列证明这家日内瓦老号能够驾驭各种强度，而不放弃它对稳定性的要求。","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"尼加拉瓜"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"厄瓜多尔深色茄衣，内裹多米尼加烟叶。介于 Signature 的细腻与 Nicaragua 的力度之间的中间系列。榛子、欧蕾咖啡、轻盈香料。它是欧洲雪茄馆里最畅销的一款——平易、稳定、令人满足。","vitolas":["Robusto","Churchill","Toro"],"wrapper":"厄瓜多尔 Colorado"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","wrapper":"未公开","vitolas":[],"story":"2009年6月从基乌萨诺家族买下的品牌，紧随2008年底的 Camacho——集团借低价位打入美国市场。本图集的普查曾把它当作一家公司。"}]' WHERE `name` = 'Davidoff';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"المجموعة المؤسِّسة — أنيفيرساريو No.1 وNo.2، أُطلقتا في كوبا عام 1968. ومنذ الانتقال إلى جمهورية الدومينيكان، صارت الأنيفيرساريو الدومينيكية مرجعًا في الرهافة بذاتها. زهور بيضاء، حبوب محمّصة، خشب الصندل. إنها تجسيد للترف من غير استعراض.","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"دومينيكي"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"أُطلقت عام 2013 تحيةً لأشهر مدخّني القرن العشرين. بالتعاون مع عائلة تشرشل، وبإذن رسمي باستخدام الاسم والأرشيف المصوَّر. أقوى من مجموعة دافيدوف الكلاسيكية — منعطف أسلوبيّ كبير. جلد، خشب مدخَّن، توابل شرقية. أما الـLate Hour فهي النسخة الليلية، وهي أشدّ.","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"مزروع في الشمس من الإكوادور"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"أُطلقت عام 2016، وهي قطيعة أسلوبية تامّة. تستكشف دافيدوف التبغ النيكاراغوي — الأقوى في قائمتها. شوكولاتة داكنة، قهوة، جلد مدبوغ. تُثبت مجموعة نيكاراغوا أن الدار الجنيفية قادرة على الإبحار في كل درجات الشدّة دون أن تتخلّى عن صرامتها في الانتظام.","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"نيكاراغوي"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"غلاف أوسكورو إكوادوري فوق تبغ دومينيكي. المجموعة الوسطى بين رهافة السيغنتشر وقوّة نيكاراغوا. بندق، قهوة بالحليب، توابل خفيفة. وهي الأكثر مبيعًا في صالات أوروبا — في المتناول، منتظمة، مُرضية.","vitolas":["Robusto","Churchill","Toro"],"wrapper":"Colorado من الإكوادور"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","wrapper":"غير معلن","vitolas":[],"story":"علامةٌ اشتُريت في حزيران/يونيو 2009 من عائلة كيوزانو، بعد Camacho في أواخر 2008 — كانت المجموعة تشتري منفذًا إلى السوق الأمريكية من أسفل سلّم الأسعار. وكان إحصاء هذا الأطلس يحسبها دارًا."}]' WHERE `name` = 'Davidoff';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : cigaraficionado.com « Davidoff Acquires Cusano » (juin 2009 : Oettinger Davidoff rachète Cusano à la famille Chiusano — fondée en 1995 par Joe et Michael Chiusano — après Camacho fin 2008 ; une marque de prix bas dans un groupe qui en vend peu)') WHERE `name` = 'Davidoff' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── Warped ──
UPDATE `brands` SET `gamme` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona","Lancero"],"story":"Un nom de marque cubaine d''avant 1960, rempli d''un assemblage contemporain. Tabacs de Jalapa, formats fins, une longueur en bouche qui vient de la matière et non de la force."},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona Gorda"],"story":"Séries courtes, souvent annoncées sans préavis. Bois, foin, une pointe de poivre blanc — le registre que la maison défend contre la mode des gros modules."},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","wrapper":"Corojo 99","vitolas":[],"story":"2016 — une collaboration avec Aganorsa, alors Casa Fernández, roulée chez eux : les bouledogues qui gardent les fermes, et des formats aux noms des chiens. Une ligne à deux maisons, pas une marque à part."},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","wrapper":"Corojo 99","vitolas":[],"story":"La seconde collaboration avec Aganorsa, 2017, même fabrique."}]' WHERE `name` = 'Warped';
UPDATE `brands` SET `gamme_en` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona","Lancero"],"story":"A pre-1960 Cuban brand name, filled with a contemporary blend. Jalapa tobaccos, slender formats, a length on the palate that comes from the material and not from strength."},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona Gorda"],"story":"Short series, often announced without warning. Wood, hay, a touch of white pepper — the register the house defends against the fashion for thick ring gauges."},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","wrapper":"Corojo 99","vitolas":[],"story":"2016 — a collaboration with Aganorsa, then Casa Fernández, rolled at their factory: the bulldogs that guard the farms, and sizes named after the dogs. A two-house line, not a separate brand."},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","wrapper":"Corojo 99","vitolas":[],"story":"The second collaboration with Aganorsa, 2017, same factory."}]' WHERE `name` = 'Warped';
UPDATE `brands` SET `gamme_es` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona","Lancero"],"story":"Un nombre de marca cubana anterior a 1960, lleno de una liga contemporánea. Tabacos de Jalapa, formatos finos, una longitud en boca que viene de la materia y no de la fuerza."},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona Gorda"],"story":"Series cortas, a menudo anunciadas sin previo aviso. Madera, heno, una pizca de pimienta blanca — el registro que la casa defiende contra la moda de los cepos gruesos."},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","wrapper":"Corojo 99","vitolas":[],"story":"2016 — una colaboración con Aganorsa, entonces Casa Fernández, liada en su fábrica: los bulldogs que guardan las fincas, y formatos con los nombres de los perros. Una línea de dos casas, no una marca aparte."},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","wrapper":"Corojo 99","vitolas":[],"story":"La segunda colaboración con Aganorsa, 2017, misma fábrica."}]' WHERE `name` = 'Warped';
UPDATE `brands` SET `gamme_de` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona","Lancero"],"story":"Ein kubanischer Markenname von vor 1960, mit einem zeitgenössischen Blend gefüllt. Jalapa-Tabake, schlanke Formate, eine Länge am Gaumen, die aus der Substanz kommt und nicht aus der Kraft."},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona Gorda"],"story":"Kurze Serien, oft ohne Vorankündigung. Holz, Heu, ein Anflug weißer Pfeffer — das Register, das das Haus gegen die Mode dicker Ringmaße verteidigt."},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","wrapper":"Corojo 99","vitolas":[],"story":"2016 — eine Zusammenarbeit mit Aganorsa, damals Casa Fernández, in deren Fabrik gerollt: die Bulldoggen, die die Farmen bewachen, und Formate mit den Namen der Hunde. Eine Linie zweier Häuser, keine eigene Marke."},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","wrapper":"Corojo 99","vitolas":[],"story":"Die zweite Zusammenarbeit mit Aganorsa, 2017, dieselbe Fabrik."}]' WHERE `name` = 'Warped';
UPDATE `brands` SET `gamme_zh` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona","Lancero"],"story":"一个1960年前的古巴品牌名，被填入当代配方。哈拉帕烟叶、细身尺寸，口中的绵长来自原料而非力度。"},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona Gorda"],"story":"小批量系列，常常毫无预告地发布。木质、干草，一丝白胡椒——这正是这家逆着粗环径潮流所捍卫的路数。"},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","wrapper":"Corojo 99","vitolas":[],"story":"2016年——与 Aganorsa（当时叫 Casa Fernández）的合作，在对方工厂卷制：守护农场的斗牛犬，尺寸以狗的名字命名。两家公司的一条线，不是独立品牌。"},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","wrapper":"Corojo 99","vitolas":[],"story":"与 Aganorsa 的第二次合作，2017年，同一家工厂。"}]' WHERE `name` = 'Warped';
UPDATE `brands` SET `gamme_ar` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona","Lancero"],"story":"اسم علامة كوبية من قبل 1960، مملوء بخلطة معاصرة. تبغ خالابا ومقاسات نحيلة، وطول في الفم يأتي من المادة لا من القوّة."},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","wrapper":"Corojo 99","vitolas":["Corona Gorda"],"story":"سلاسل قصيرة، غالباً بلا إعلان مسبق. خشب وقشّ ولمسة فلفل أبيض — المزاج الذي تدافع عنه الدار في وجه موضة الأقطار السميكة."},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","wrapper":"Corojo 99","vitolas":[],"story":"2016 — تعاونٌ مع Aganorsa، التي كانت آنذاك Casa Fernández، يُلفّ في مصنعها: كلاب البولدوغ التي تحرس المزارع، وقياسات بأسماء الكلاب. خطٌّ لدارين، لا علامة مستقلّة."},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","wrapper":"Corojo 99","vitolas":[],"story":"التعاون الثاني مع Aganorsa، 2017، المصنع نفسه."}]' WHERE `name` = 'Warped';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 : halfwheel.com « Guardian of the Farm Apollo Selección de Warped » (Guardian of the Farm, collaboration avec Casa Fernández lancée en 2016, hommage aux bouledogues qui gardent les fermes Aganorsa ; formats aux noms des chiens — Apollo, JJ, Campeón, Rambo)') WHERE `name` = 'Warped' AND COALESCE(`source`,'') NOT LIKE '%lot 5 :%';

-- ── J.C. Newman : le paragraphe faux, six langues ──
UPDATE `brands` SET `history` = REPLACE(`history`, 'Côté premium, la famille ne roule rien elle-même : ses deux marques hautes, Diamond Crown et Cuesta-Rey, sortent de la Tabacalera A. Fuente, en République dominicaine. Chacune a sa fiche dans cet atlas, classée là-bas pour cette raison. El Reloj, lui, reste à Tampa.', 'Ses deux marques hautes, Diamond Crown et Cuesta-Rey, sortent de la Tabacalera A. Fuente, en République dominicaine ; chacune a sa fiche dans cet atlas, classée là-bas pour cette raison. Mais la famille roule aussi elle-même, et une première version de cette fiche disait le contraire : depuis 2011, elle possède à Estelí une fabrique, PENSA — Puros de Estelí Nicaragua S.A. —, ouverte avec Quorum et El Baton, où Perla del Mar puis Brick House ont suivi, et qui roule plus de cent mille cigares par jour. Omar Ortez, dont l''atlas raconte Agrotabacos, la co-dirige avec Lázaro López. El Reloj, lui, reste à Tampa.') WHERE `name` = 'J.C. Newman';
UPDATE `brands` SET `history_en` = REPLACE(`history_en`, 'On the premium side, the family rolls nothing itself: its two top brands, Diamond Crown and Cuesta-Rey, come out of Tabacalera A. Fuente, in the Dominican Republic. Each has its own entry in this atlas, filed there for that reason. El Reloj, for its part, stays in Tampa.', 'Its two top brands, Diamond Crown and Cuesta-Rey, come out of Tabacalera A. Fuente, in the Dominican Republic; each has its own entry in this atlas, filed there for that reason. But the family also rolls itself, and a first version of this entry said the opposite: since 2011 it has owned a factory in Estelí, PENSA — Puros de Estelí Nicaragua S.A. — opened with Quorum and El Baton, where Perla del Mar and then Brick House followed, and which rolls more than a hundred thousand cigars a day. Omar Ortez, whose Agrotabacos this atlas tells, co-runs it with Lázaro López. El Reloj, for its part, stays in Tampa.') WHERE `name` = 'J.C. Newman';
UPDATE `brands` SET `history_es` = REPLACE(`history_es`, 'En el terreno premium, la familia no lía nada ella misma: sus dos marcas altas, Diamond Crown y Cuesta-Rey, salen de la Tabacalera A. Fuente, en la República Dominicana. Cada una tiene su ficha en este atlas, clasificada allí por esa razón. El Reloj, en cambio, se queda en Tampa.', 'Sus dos marcas altas, Diamond Crown y Cuesta-Rey, salen de la Tabacalera A. Fuente, en la República Dominicana; cada una tiene su ficha en este atlas, clasificada allí por esa razón. Pero la familia también lía ella misma, y una primera versión de esta ficha decía lo contrario: desde 2011 posee en Estelí una fábrica, PENSA — Puros de Estelí Nicaragua S.A. —, abierta con Quorum y El Baton, donde siguieron Perla del Mar y luego Brick House, y que lía más de cien mil puros al día. Omar Ortez, cuya Agrotabacos cuenta este atlas, la codirige con Lázaro López. El Reloj, en cambio, se queda en Tampa.') WHERE `name` = 'J.C. Newman';
UPDATE `brands` SET `history_de` = REPLACE(`history_de`, 'Auf der Premiumseite rollt die Familie nichts selbst: Ihre beiden Spitzenmarken, Diamond Crown und Cuesta-Rey, kommen aus der Tabacalera A. Fuente in der Dominikanischen Republik. Beide haben in diesem Atlas einen eigenen Eintrag und stehen aus eben diesem Grund dort. El Reloj dagegen bleibt in Tampa.', 'Ihre beiden Spitzenmarken, Diamond Crown und Cuesta-Rey, kommen aus der Tabacalera A. Fuente in der Dominikanischen Republik; beide haben in diesem Atlas einen eigenen Eintrag und stehen aus eben diesem Grund dort. Aber die Familie rollt auch selbst, und eine erste Fassung dieses Eintrags sagte das Gegenteil: Seit 2011 besitzt sie in Estelí eine Fabrik, PENSA — Puros de Estelí Nicaragua S.A. —, eröffnet mit Quorum und El Baton, wo Perla del Mar und dann Brick House folgten, und die über hunderttausend Zigarren am Tag rollt. Omar Ortez, dessen Agrotabacos dieser Atlas erzählt, leitet sie gemeinsam mit Lázaro López. El Reloj dagegen bleibt in Tampa.') WHERE `name` = 'J.C. Newman';
UPDATE `brands` SET `history_zh` = REPLACE(`history_zh`, '在优质产品线一侧，这个家族并不自己卷制：旗下两个高端品牌 Diamond Crown 与 Cuesta-Rey 均出自多米尼加共和国的 Tabacalera A. Fuente。二者在本图集中各有专条，也正因如此归在那里。而 El Reloj 仍留在坦帕。', '旗下两个高端品牌 Diamond Crown 与 Cuesta-Rey 出自多米尼加共和国的 Tabacalera A. Fuente；二者在本图集中各有专条，也正因如此归在那里。但这个家族也自己卷制，而本词条的初版说的恰恰相反：自2011年起，它在埃斯特利拥有一家工厂 PENSA——Puros de Estelí Nicaragua S.A.——以 Quorum 与 El Baton 开厂，随后有了 Perla del Mar 与 Brick House，日产超过十万支。奥马尔·奥尔特斯——本图集在 Agrotabacos 词条讲过他——与拉萨罗·洛佩斯共同管理。而 El Reloj 仍留在坦帕。') WHERE `name` = 'J.C. Newman';
UPDATE `brands` SET `history_ar` = REPLACE(`history_ar`, 'أمّا في الفاخر، فالعائلة لا تلفّ شيئًا بنفسها: علامتاها الكبريان، «دايموند كراون» و«كويستا-ري»، تخرجان من تاباكاليرا أ. فوينتي في الجمهورية الدومينيكية. ولكلٍّ منهما بطاقتها في هذا الأطلس، وهي مصنّفة هناك لهذا السبب بالذات. أمّا «إل ريلوخ» فيبقى في تامبا.', 'علامتاها الكبريان، «دايموند كراون» و«كويستا-ري»، تخرجان من تاباكاليرا أ. فوينتي في الجمهورية الدومينيكية؛ ولكلٍّ منهما بطاقتها في هذا الأطلس، وهي مصنّفة هناك لهذا السبب بالذات. لكنّ العائلة تلفّ بنفسها أيضًا، وكانت نسخة أولى من هذه البطاقة تقول العكس: فمنذ 2011 تملك في إستيلي مصنعًا، PENSA — Puros de Estelí Nicaragua S.A. —، افتُتح بـQuorum وEl Baton، ثم تبعتهما Perla del Mar فBrick House، ويلفّ ما يزيد على مئة ألف سيجار في اليوم. ويشارك في إدارته عمر أورتيس، الذي يروي هذا الأطلس Agrotabacos الخاصة به، مع لاثارو لوبيس. أمّا «إل ريلوخ» فيبقى في تامبا.') WHERE `name` = 'J.C. Newman';

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'history' champ UNION ALL SELECT 'gamme') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Black Label Trading Co.','Aganorsa Leaf','J.C. Newman','La Aurora','Drew Estate','Rocky Patel','Tatuaje','RoMa Craft Tobac','A.J. Fernandez','Espinosa','Davidoff','Warped')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 214';
INSERT INTO `moderation_log`
  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 214','systeme','lot_5_seize_lignes_requalifiees','marque',0,
   'Seize lignes entrent dans le gamme de leur maison, six langues : BLK WKS, Condega, Brick House, Perla del Mar, Quorum, Leon Jimenes, Herrera Esteli, Kentucky Fire Cured, Hamlet, Cabaiguan, Baka, Enclave, Dias de Gloria, 601, Cusano, Guardian of the Farm'),
  (NULL,'migration 214','systeme','jc_newman_corrigee_pensa','marque',0,
   'La fiche disait que la famille ne roule rien elle-meme. Faux depuis 2011 : PENSA a Esteli roule Quorum, Perla del Mar et Brick House, co-dirigee par Omar Ortez. Paragraphe remplace en six langues, l erreur nommee dans la fiche'),
  (NULL,'migration 214','systeme','requalifications_non_traitees','marque',0,
   'Archetype/Psyko Seven : Ventura sans fiche. Lost & Found : societe a part, pas une ligne de Caldwell. Belinda : marque retiree, aucune source verifiee. Deadwood, Isla del Sol, 20 Acre Farm, Indomina : non sources dans ce lot');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Black Label Trading Co.','Aganorsa Leaf','J.C. Newman','La Aurora','Drew Estate','Rocky Patel','Tatuaje','RoMa Craft Tobac','A.J. Fernandez','Espinosa','Davidoff','Warped') AND `gamme` LIKE '%"vitolas"%') = 12 AS onze_gammes,
  (SELECT `gamme_ar` LIKE '%Brick House%' AND `gamme_zh` LIKE '%Quorum%' FROM `brands` WHERE `name` = 'J.C. Newman') AS newman_gamme,
  (SELECT `history` LIKE '%PENSA%' AND `history_ar` LIKE '%PENSA%' AND `history` NOT LIKE '%ne roule rien%' FROM `brands` WHERE `name` = 'J.C. Newman') AS newman_corrigee,
  (SELECT `gamme` LIKE '%Hamlet%' AND `gamme_de` LIKE '%Tabaquero%' FROM `brands` WHERE `name` = 'Rocky Patel') AS hamlet,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 214') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
